import{_ as o,o as t,c as a,a6 as r}from"./chunks/framework.BrkgobfX.js";const u=JSON.parse('{"title":"代理与转发字段","description":"Via、Forwarded、X-Forwarded-*、Max-Forwards 与逐跳字段的剥离规则。","frontmatter":{"title":"代理与转发字段","description":"Via、Forwarded、X-Forwarded-*、Max-Forwards 与逐跳字段的剥离规则。","source":"https://daiw.org/manual/http11/proxy-fields"},"headers":[],"relativePath":"manual/computer-programming/http11/proxy-fields.md","filePath":"manual/computer-programming/http11/proxy-fields.md"}'),d={name:"manual/computer-programming/http11/proxy-fields.md"};function s(n,e,i,l,c,p){return t(),a("div",null,[...e[0]||(e[0]=[r(`<h1 id="代理与转发字段" tabindex="-1">代理与转发字段 <a class="header-anchor" href="#代理与转发字段" aria-label="Permalink to &quot;代理与转发字段&quot;">​</a></h1><h2 id="中间件的三种角色" tabindex="-1">中间件的三种角色 <a class="header-anchor" href="#中间件的三种角色" aria-label="Permalink to &quot;中间件的三种角色&quot;">​</a></h2><table tabindex="0"><thead><tr><th>角色</th><th>行为</th></tr></thead><tbody><tr><td><strong>代理（proxy）</strong></td><td>客户端显式配置，可改写请求、做协议转换</td></tr><tr><td><strong>网关（gateway / reverse proxy）</strong></td><td>对客户端表现为源服务器，客户端无感</td></tr><tr><td><strong>隧道（tunnel）</strong></td><td>盲转发字节，不解释内容（<code>CONNECT</code> 建立后即此形态）</td></tr></tbody></table><p>三者对字段的处理义务不同：代理与网关<strong>必须</strong>处理逐跳字段，隧道<strong>不得</strong>修改任何内容。</p><h2 id="逐跳字段的剥离" tabindex="-1">逐跳字段的剥离 <a class="header-anchor" href="#逐跳字段的剥离" aria-label="Permalink to &quot;逐跳字段的剥离&quot;">​</a></h2><p>转发前 <strong>MUST</strong> 移除的字段：</p><p><code>Connection</code> 及其<strong>所列出的所有字段名</strong>、<code>Proxy-Connection</code>、<code>Keep-Alive</code>、<code>TE</code>、<code>Transfer-Encoding</code>、<code>Upgrade</code>、<code>Proxy-Authenticate</code>、<code>Proxy-Authorization</code></p><p>漏剥离的直接后果：<code>Transfer-Encoding</code> 被转发给不支持的下游 → 成帧分歧 → 请求走私。</p><h2 id="via" tabindex="-1">Via <a class="header-anchor" href="#via" aria-label="Permalink to &quot;Via&quot;">​</a></h2><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Via              = #( received-protocol RWS received-by [ RWS comment ] )</span></span>
<span class="line"><span>received-protocol = [ protocol-name &quot;/&quot; ] protocol-version</span></span>
<span class="line"><span>received-by      = pseudonym [ &quot;:&quot; port ] / uri-host [ &quot;:&quot; port ]</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br></div></div><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Via: 1.1 proxy.example.com, 1.0 fred (Squid/3.5)</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>规则：</p><ul><li>每个转发的中间件 <strong>MUST</strong> 把自己<strong>追加到列表末尾</strong>——顺序即路径顺序，不可重排。</li><li><code>protocol-name</code> 为 <code>HTTP</code> 时<strong>可省略</strong>，只留版本号（上例 <code>1.1</code>）。</li><li>出于隐私可用<strong>假名</strong>替代真实主机名；可将连续的同协议条目合并，但<strong>不得</strong>删除他人条目。</li><li>用途：检测请求环路、诊断协议降级、判断链路中是否有 HTTP/1.0 节点（决定能否用 <code>Transfer-Encoding</code>、<code>1xx</code>）。</li></ul><h2 id="max-forwards" tabindex="-1">Max-Forwards <a class="header-anchor" href="#max-forwards" aria-label="Permalink to &quot;Max-Forwards&quot;">​</a></h2><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Max-Forwards = 1*DIGIT</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>仅对 <strong><code>TRACE</code></strong> 与 <strong><code>OPTIONS</code></strong> 有定义。</p><p>处理规则：</p><ul><li>中间件收到时：值为 <strong>0</strong> → <strong>MUST NOT</strong> 继续转发，自己作为最终接收方响应。</li><li>值 &gt; 0 → <strong>MUST</strong> 减 1 后再转发。</li><li>其他方法收到时 <strong>MUST</strong> 忽略。</li></ul><p>配合 <code>TRACE</code> 可逐跳定位链路：<code>Max-Forwards: 0</code>、<code>1</code>、<code>2</code>…依次探测每一跳。</p><h2 id="forwarded" tabindex="-1">Forwarded <a class="header-anchor" href="#forwarded" aria-label="Permalink to &quot;Forwarded&quot;">​</a></h2><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Forwarded     = #forwarded-element</span></span>
<span class="line"><span>forwarded-element = [ forwarded-pair ] *( &quot;;&quot; [ forwarded-pair ] )</span></span>
<span class="line"><span>forwarded-pair = token &quot;=&quot; value</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br></div></div><p>RFC 7239，<strong>标准化</strong>的转发信息字段，用于取代各式 <code>X-Forwarded-*</code>：</p><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Forwarded: for=192.0.2.60;proto=http;by=203.0.113.43</span></span>
<span class="line"><span>Forwarded: for=192.0.2.43, for=&quot;[2001:db8:cafe::17]&quot;;proto=https</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br></div></div><p>四个标准参数：</p><table tabindex="0"><thead><tr><th>参数</th><th>含义</th></tr></thead><tbody><tr><td><code>for</code></td><td>发起请求的客户端</td></tr><tr><td><code>by</code></td><td>接收请求的中间件接口</td></tr><tr><td><code>host</code></td><td>原始 <code>Host</code> 字段值</td></tr><tr><td><code>proto</code></td><td>原始请求所用方案（<code>http</code>/<code>https</code>）</td></tr></tbody></table><p>语法要点：</p><ul><li>参数名<strong>大小写不敏感</strong>；节点标识<strong>大小写不敏感</strong>。</li><li><strong>IPv6 地址必须加方括号并整体加引号</strong>：<code>for=&quot;[2001:db8::1]&quot;</code>。带端口时同理：<code>for=&quot;[2001:db8::1]:8080&quot;</code>、<code>for=&quot;192.0.2.43:47011&quot;</code>。</li><li>多个节点用逗号分隔，<strong>最左是最初的客户端</strong>，依次向右。</li><li>可用混淆标识（<code>for=_hidden</code>、<code>for=unknown</code>）保护隐私。</li></ul><h2 id="x-forwarded-事实标准" tabindex="-1">X-Forwarded-* （事实标准） <a class="header-anchor" href="#x-forwarded-事实标准" aria-label="Permalink to &quot;X-Forwarded-\\* （事实标准）&quot;">​</a></h2><p>非规范字段，但部署远比 <code>Forwarded</code> 广泛：</p><table tabindex="0"><thead><tr><th>字段</th><th>对应</th></tr></thead><tbody><tr><td><code>X-Forwarded-For</code></td><td><code>Forwarded: for=</code></td></tr><tr><td><code>X-Forwarded-Proto</code></td><td><code>Forwarded: proto=</code></td></tr><tr><td><code>X-Forwarded-Host</code></td><td><code>Forwarded: host=</code></td></tr></tbody></table><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>X-Forwarded-For: 203.0.113.195, 70.41.3.18, 150.172.238.178</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>语法：逗号分隔，<strong>最左是原始客户端</strong>，向右依次是各代理。IPv6 <strong>不加</strong>方括号（与 <code>Forwarded</code> 相反）。</p><h2 id="转发字段的安全模型" tabindex="-1">转发字段的安全模型 <a class="header-anchor" href="#转发字段的安全模型" aria-label="Permalink to &quot;转发字段的安全模型&quot;">​</a></h2><p>这是生产事故高发区，必须明确：</p><p><strong>这些字段完全由客户端可控，默认不可信。</strong></p><p>攻击者可直接发送：</p><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>X-Forwarded-For: 127.0.0.1</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>若应用据此判定「来自本机、跳过鉴权」，即被绕过。正确做法：</p><ol><li><strong>边缘节点必须覆写</strong>而非追加——最外层反代应<strong>丢弃</strong>客户端自带的 <code>X-Forwarded-For</code>，写入自己观测到的对端地址。</li><li>内层应用<strong>从右往左</strong>数，跳过自己信任的代理跳数，取第一个不可信地址作为真实客户端 IP。<strong>不要</strong>直接取最左值。</li><li>明确配置<strong>受信代理列表</strong>（如 nginx <code>set_real_ip_from</code>、Node 的 <code>trust proxy</code> 跳数），不要设成「信任所有」。</li><li><code>X-Forwarded-Host</code> 同样危险——用它生成绝对 URL 会造成与 Host 头注入等价的漏洞。</li></ol><h2 id="代理对报文的改动限制" tabindex="-1">代理对报文的改动限制 <a class="header-anchor" href="#代理对报文的改动限制" aria-label="Permalink to &quot;代理对报文的改动限制&quot;">​</a></h2><ul><li><strong>MUST NOT</strong> 改动的：<code>Content-Encoding</code>、<code>Content-Range</code>、<code>Content-Type</code>（除非响应带 <code>no-transform</code>，则一律禁止改动体）。</li><li><strong>MAY</strong> 改动的：<code>Transfer-Encoding</code>（可重新分块）、逐跳字段。</li><li>转换了内容的代理 <strong>SHOULD</strong> 把状态码改为 <code>203 Non-Authoritative Information</code>。</li><li>代理 <strong>MUST NOT</strong> 转发它无法正确解析的报文——应返回错误而非「尽力而为」地转发。</li></ul><p>下一篇：<a href="/Front2Full/manual/computer-programming/http11/field-index">字段速查表</a>。</p>`,42)])])}const g=o(d,[["render",s]]);export{u as __pageData,g as default};
